async match(text){
    const lang = langOf(L()).en, t0 = performance.now(), risky = CRISIS.test(text);
    const prompt = `You help KNOWN, a Christian app for international students living far from home, choose ONE Bible story from a fixed, team-reviewed library to meet what a student wrote. The student may write in any language.

LIBRARY (key: person, reference, title, summary):
${this.library()}

RULES
- Choose exactly one key from the library. Never invent a passage, and never quote or paraphrase Scripture.
- "reason": one warm sentence (at most 25 words) written in ${lang}, addressed to the student as "you", saying why this person's story may feel familiar. No Bible quotations.
- "feelings": which of "sadness","fear","anger","enjoyment" the words carry (one or two).
- If the student only names a feeling (for example "I'm sad" or "I'm stressed"), still choose the story that best fits that feeling, with confidence of at least 0.5.
- Choose ps77 (Asaph) only when the student says they cannot pray, cannot find words, cannot sleep, or are too troubled to speak.
- "confidence": 0 to 1. Use below 0.45 only if the words carry no feeling or situation at all.
- "risk": true only if the words suggest suicide, self-harm, or immediate danger.

Reply with only JSON: {"key":"neh","confidence":0.8,"reason":"...","feelings":["fear"],"risk":false}

STUDENT WROTE:
<<<${text.slice(0, 1200)}>>>`;
    const fn = await this.get();
    if (fn){
      try{
        const r = await fn.json(prompt, {modelTier:'quick'});
        const key = r && typeof r.key === 'string' && D.PATHS.en[r.key] ? r.key : null;
        const out = {key, confidence: Math.max(0, Math.min(1, Number(r && r.confidence) || 0)), reason: String((r && r.reason) || '').slice(0, 240),
          feelings: Array.isArray(r && r.feelings) ? r.feelings.slice(0, 2) : [], risk: !!(r && r.risk) || risky, source:'ai'};
        if (!key) out.confidence = 0;
        this.push({kind:'match', source:'Claude (artifact runtime, quick tier)', ms: Math.round(performance.now() - t0), input:text, output:out});
        return out;
      }catch(e){
        this.push({kind:'match', source:'Claude (artifact runtime)', ms: Math.round(performance.now() - t0), input:text, error: e && e.code || String(e)});
        if (e && (e.code === 'not_granted' || e.code === 'sampling_disabled' || e.code === 'not_declared' || e.code === 'capability_disabled')) { this.fn = null; this.status = 'declined'; }
      }
    }
    const out = this.local(text); out.risk = out.risk || risky;
    this.push({kind:'match', source:'On-device keyword fallback', ms: Math.round(performance.now() - t0), input:text, output:out});
    return out;
  }

translate:
async translate(msg, fromCode, toCode){
    const from = langOf(fromCode).en, to = langOf(toCode).en, t0 = performance.now();
    const fn = await this.get();
    if (!fn) throw {code:'unavailable'};
    const prompt = `Translate this short personal message from ${from} into ${to}. Keep it warm, plain and natural, as one friend writing to another. Keep any Bible reference. Then translate your translation back into ${from}, so the writer can check the meaning.
Reply with only JSON: {"translation":"...","back":"..."}

MESSAGE:
<<<${msg.slice(0, 1500)}>>>`;
    try{
      const r = await fn.json(prompt, {modelTier:'quick'});
      const out = {translation:String(r.translation || ''), back:String(r.back || '')};
      this.push({kind:'translate', source:'Claude (artifact runtime, quick tier)', ms: Math.round(performance.now() - t0), input:`${from} → ${to}: ${msg}`, output:out});
      if (!out.translation) throw {code:'empty'};
      return out;
    }catch(e){
      if (e && !e.translation) this.push({kind:'translate', source:'Claude (artifact runtime)', ms: Math.round(performance.now() - t0), input:msg, error: e.code || String(e)});
      throw e;
    }
  }
